import { Router } from 'express';
import { submitResponse, checkSubmissionStatus, clearSubjectData, submitResponseSchema, } from '../controllers/responseController.js';
import { validate } from '../middleware/validate.js';
import { requireAuth, authorizeRoles } from '../middleware/auth.js';
const router = Router();
router.use(requireAuth);
router.post('/submit', authorizeRoles('student'), validate(submitResponseSchema), submitResponse);
router.get('/status/:subjectId', authorizeRoles('student', 'teacher', 'admin'), checkSubmissionStatus);
router.delete('/clear/:subjectId', authorizeRoles('admin'), clearSubjectData);
export default router;
